entries[62343] = { ["name"] = "Hitze", ["text"] = "100 Meter Reichweite\nSofort\nÜberzieht alle nahen Eisenkonstrukte mit intensiver Hitze, was ihr Bewegungstempo um 5 und ihr Tempo um 5 erhöht. Dieser Effekt ist bis zu 10-mal stapelbar. Wenn der Effekt 10 Stapel erreicht hat, wird das betroffene Eisenkonstrukt schmelzen." }
entries[62344] = { ["name"] = "Fäuste aus Stein", ["text"] = "Wirken in 2.5 sek. 10 sek. Abklingzeit\nDie Steinfäuste verlangsamen das Bewegungstempo des Zaubernden um 20% und erhöhen den verursachten Schaden um 250%. Zusätzlich haben die vernichtenden Angriffe die Chance, dem Ziel die Knochen zu brechen, was dessen Chance zu blockieren, auszuweichen oder zu parieren 20 sec lang um 100% senkt.\n(5s Abklingzeit)" }
entries[62345] = { ["name"] = "Rammen", ["text"] = "40 Energie 15 Meter Reichweite\nSofort\nRammt alle Feinde, die sich vor dem Verwüster befinden, verursacht 22501 to 27501 Schaden und stößt sie zurück. Verursacht zudem bei Gebäuden 2850 to 3150 Belagerungsschaden." }
entries[62346] = { ["name"] = "Volldampf voraus!", ["text"] = "40 Energie 70 Meter Reichweite\nSofort 15 sek. Abklingzeit\nSchaltet die Dampfmaschine eine kurze Zeit lang in den Turbogang und lässt sie nach vorne schnellen. Verursacht dabei Belagerungsschaden und schleudert Feinde zurück." }
entries[62347] = { ["name"] = "Netherschock", ["text"] = "20 Meter Reichweite\nSofort 40 sek. Abklingzeit\nÜberzieht einen Feind sofort mit Schattenschaden. Unterbricht zudem das Wirken von Zaubern und verhindert 2 sec lang, dass ein Zauber dieser Art gewirkt werden kann." }
entries[62348] = { ["name"] = "Schwarzes Loch - sichtbares Ziel" }
entries[62349] = { ["name"] = "Satt", ["text"] = "Sofort\nTrefferwertung um 30 und Ausdauer um 40 erhöht. Hält 1 hour lang an." }
entries[62350] = { ["name"] = "Worgtatar", ["text"] = "Wirken in 4 sek.\nReagenzien:\nWorgschenkel (2), Nordische Gewürze\nDiese Delikatesse wird am Besten roh serviert und benötigt deshalb keine Kochstelle.\n70\nBenutzen: Stellt im Verlauf von 30 sec 22500 Gesundheit und 19200 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 1 hour lang 40 Trefferwertung und 40 Ausdauer." }
entries[62351] = { ["name"] = "Erfrischung", ["text"] = "Sofort\nStellt im Verlauf von 30 sec insgesamt 22500 Gesundheit wieder her. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 1 hour lang 30 Trefferwertung und 40 Ausdauer." }
entries[62352] = { ["name"] = "Heilen", ["text"] = "Sofort\nStellt 280 to 360 Gesundheit wieder her." }
entries[62353] = { ["name"] = "Glyphe 'Arkanschlag'", ["text"] = "Wirken in 5 sek.\nErhöht den Schaden Eures Stärkungszaubers 'Arkanschlag' um 3%." }
